import 'jest';
import { getFirstChildNode, xmlNodeToString } from '../../src';

describe('XML Parsing', () => {
    describe('with no native DOMParser', () => {
        let windowSpy: jest.SpyInstance;

        beforeEach(() => {
            windowSpy = jest.spyOn(globalThis, 'window', 'get');
            windowSpy.mockImplementation(() => ({
                DOMParser: null
            }));
        });

        afterEach(() => {
            windowSpy.mockRestore();
        });

        test('will return null', () => {
            const xmlString = '<>';
            const parsedXml = getFirstChildNode(xmlString);
            expect(parsedXml).toBe(null);
        });
    });

    describe('with no native ActiveXObject', () => {
        let windowSpy: jest.SpyInstance;

        beforeEach(() => {
            windowSpy = jest.spyOn(globalThis, 'window', 'get');
            windowSpy.mockImplementation(() => ({
                ActiveXObject: null
            }));
        });

        afterEach(() => {
            windowSpy.mockRestore();
        });

        test('will return null', () => {
            const xmlString = '<>';
            const parsedXml = getFirstChildNode(xmlString);
            expect(parsedXml).toBe(null);
        });
    });

    describe('with native DOMParser', () => {
        test('can parse xml', () => {
            const xmlString = '<foo bar="1" baz="false"></foo>';
            const parsedXml = getFirstChildNode(xmlString);

            if (parsedXml === null) {
                throw new Error('XML Parsing Failed');
            }

            expect(parsedXml.name).toBe('foo');
            expect(parsedXml.attributes.bar).toBe('1');
            expect(parsedXml.attributes.baz).toBe('false');
        });

        test('can parse nested xml', () => {
            const xmlString = '<foo bar="2"><bar baz="true"></bar></foo>';
            const parsedXml = getFirstChildNode(xmlString);

            if (parsedXml === null) {
                throw new Error('XML Parsing Failed');
            }

            expect(parsedXml.name).toBe('foo');
            expect(parsedXml.attributes.bar).toBe('2');
            expect(parsedXml.childNodes.bar[0].name).toBe('bar');
            expect(parsedXml.childNodes.bar[0].attributes.baz).toBe('true');
        });
    });

    describe('with native ActiveXObject', () => {
        let windowSpy: jest.SpyInstance;
        let mockLoadXML: jest.SpyInstance;

        beforeEach(() => {
            mockLoadXML = jest.fn(() => ({}));
            const activeXObject = jest.fn().mockImplementation(() => {
                return { loadXML: mockLoadXML };
            });

            windowSpy = jest.spyOn(globalThis, 'window', 'get');
            windowSpy.mockImplementation(() => ({
                DOMParser: null,
                ActiveXObject: activeXObject
            }));
        });

        afterEach(() => {
            windowSpy.mockRestore();
        });

        test('will attempt to parse XML', () => {
            const xmlString = '<foo bar="1" baz="false"></foo>';
            getFirstChildNode(xmlString);
            expect(mockLoadXML).toHaveBeenCalled();
        });
    });
});




describe('xmlNodeToString()', () => {
    test('should format a simple xml node that only supplies a name', () => {
        expect(xmlNodeToString({
            name: 'admin'
        })).toEqual('<admin/>');
    });
    test('should format a simple xml node that only supplies a name and attributes', () => {
        expect(xmlNodeToString({
            name: 'admin',
            attributes: {
                command: 'auth',
                key: 'value'
            }
        })).toEqual('<admin command="auth" key="value"/>');
    });

    test('should format a simple xml node that only supplies a name and attributes', () => {
        expect(xmlNodeToString({
            name: 'admin',
            attributes: {
                command: 'auth',
                key: 'value'
            },
            childNodes: {
                club: [
                    {
                        name: 'club',
                        attributes: {
                            id: '1',
                            playercount: '30'
                        }
                    }
                ]
            }
        })).toEqual('<admin command="auth" key="value"><club id="1" playercount="30"/></admin>');
    });
});